function properDivisors(n){ var out=[], i; for(i=1;i<=n/2;i++){ if(n%i===0) out.push(i); } return out; }
function isPerfect(n){
  n=Math.floor(Math.abs(+n));
  if(isNaN(n)||n<2) return {error:'请输入 ≥2 的整数'};
  var div=properDivisors(n), sum=div.reduce(function(a,b){return a+b;},0);
  return {value:n, isPerfect:sum===n, sum:sum, divisors:div};
}
function perfectUpTo(limit){
  limit=Math.floor(+limit)||10000;
  if(limit<2||limit>1e7) return {error:'上限须 2–1e7'};
  var out=[], n;
  for(n=2;n<=limit;n++){ var div=properDivisors(n), sum=div.reduce(function(a,b){return a+b;},0); if(sum===n) out.push(n); }
  return {value:out};
}
var EXPORTS={isPerfect:isPerfect, perfectUpTo:perfectUpTo};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PerfectForgePure = EXPORTS; }
